<?php
namespace PortOpener\Http\Controllers;
use Illuminate\Http\Request;use PortOpener\Services\{ServicePairing,OutboundPublisher};use PortOpener\Models\SyncState;
class NodeServiceController {
public function pair(Request $request,ServicePairing $pairing){$data=$request->validate(['pairing_code'=>['required','string','regex:/^[a-f0-9]{64}$/D']]);return response()->json($pairing->exchange($data['pairing_code']));}
public function renew(Request $request,ServicePairing $pairing){return response()->json($pairing->renew($request->attributes->get('port_opener_credential')));}
public function desired(Request $request,OutboundPublisher $publisher){$policy=$request->attributes->get('port_opener_policy');$configuration=$publisher->configuration($policy);$body=$publisher->publish($policy);$policy->refresh();return response()->json(['schema_version'=>1,'configuration'=>$configuration,'desired_state'=>$body,'test_request_id'=>$policy->test_request_id,'ipv6_mapping_ids'=>$policy->ipv6_mapping_ids ?? [],'diagnostics_control'=>['debug_until'=>$policy->debug_until?->isFuture() ? $policy->debug_until->toIso8601String() : null]]);}
public function report(Request $request){return \Illuminate\Support\Facades\DB::transaction(function()use($request){
$policy=\PortOpener\Models\NodePolicy::whereKey($request->attributes->get('port_opener_policy')->id)->lockForUpdate()->firstOrFail();$data=$request->validate(['diagnostics'=>['sometimes','array'],'diagnostics.schema_version'=>['required_with:diagnostics','integer','in:1'],'diagnostics.service_version'=>['nullable','string','max:40'],'diagnostics.python_version'=>['nullable','string','max:40'],'diagnostics.debug_active'=>['sometimes','boolean'],'diagnostics.debug_until'=>['nullable','string','max:40'],'diagnostics.storage_ok'=>['sometimes','boolean'],'diagnostics.events'=>['sometimes','array','max:128'],'status'=>['required','array'],'status.schema_version'=>['required','integer','in:1'],'status.generation'=>['required','integer','min:0'],'status.mappings'=>['present','array','max:256'],
'status.ipv6'=>['sometimes','array'],'status.backend'=>['sometimes','in:fake,upnp'],'status.dry_run'=>['sometimes','boolean'],'status.router_reachable'=>['sometimes','boolean'],'status.router_url'=>['nullable','string','max:2048'],'status.last_reconciled_at'=>['nullable','string','max:40'],'status.renewal_paused'=>['sometimes','boolean'],
'status.router_service'=>['nullable','in:urn:schemas-upnp-org:service:WANIPConnection:1,urn:schemas-upnp-org:service:WANIPConnection:2,urn:schemas-upnp-org:service:WANPPPConnection:1'],
'status.mappings.*.mapping_id'=>['required','string','max:128','regex:/^[a-f0-9-]{36}:[0-9]+:(tcp|udp)$/D'],'status.mappings.*.port'=>['required','integer','between:1,65535'],'status.mappings.*.protocol'=>['required','in:TCP,UDP'],'status.mappings.*.state'=>['required','in:pending,mapped,conflict,blocked,error,removing,removed'],
'status.mappings.*.error_code'=>['nullable','string','max:64'],'status.mappings.*.message'=>['nullable','string','max:1024'],
'test_request_id'=>['nullable','uuid'],'test_result'=>['nullable','array'],'test_result.backend'=>['sometimes','in:fake,upnp'],'test_result.router_reachable'=>['sometimes','boolean'],'test_result.message'=>['nullable','string','max:1024'],'test_result.service_type'=>['nullable','string','max:256']]);
abort_unless($data['status']['generation']<=(int)$policy->desired_generation,409,'Unpublished generation.');
abort_unless($data['status']['generation']>=(int)($policy->last_report['generation'] ?? 0),409,'Stale report generation.');
$allowed=collect(array_merge($policy->desired_snapshot['mappings'] ?? [],$policy->last_report['mappings'] ?? [],$policy->last_report['ipv6']['mappings'] ?? [],SyncState::where('installation_id',$policy->installation_id)->first()?->last_status['mappings'] ?? []))->keyBy('mapping_id');
$rows=[];foreach($data['status']['mappings'] as $row){$expected=$allowed->get($row['mapping_id']);abort_unless($expected && (int)$expected['port']===(int)$row['port'] && $expected['protocol']===$row['protocol'],422,'Mapping is outside this node snapshot.');$rows[]=['mapping_id'=>$row['mapping_id'],'port'=>$row['port'],'protocol'=>$row['protocol'],'state'=>$row['state'],'error_code'=>isset($row['error_code']) && preg_match('/^[a-z0-9_]{1,64}$/D',(string)$row['error_code'])?$row['error_code']:null,'message'=>match($row['state']){'conflict'=>'External port is already in use.','error'=>'Router operation failed.','blocked'=>'Mapping blocked by service policy.',default=>'Service reported '.$row['state'].'.'}];}
$reportedUrl=$data['status']['router_url'] ?? null;
$reconciled=null;$reportedTime=$data['status']['last_reconciled_at'] ?? null;
if(is_string($reportedTime) && strlen($reportedTime)<=40){try{$time=\Illuminate\Support\Carbon::parse($reportedTime);if($time->lte(now()->addSeconds(30)) && $time->gte(now()->subYear()))$reconciled=$time->toIso8601String();}catch(\Throwable $e){}}
$status=['schema_version'=>1,'generation'=>$data['status']['generation'],'mappings'=>$rows,'backend'=>($data['status']['backend'] ?? '')==='fake'?'fake':'upnp','router_reachable'=>(bool)($data['status']['router_reachable'] ?? false),'dry_run'=>(bool)($data['status']['dry_run'] ?? true),'renewal_paused'=>(bool)($data['status']['renewal_paused'] ?? false),'router_url'=>is_string($reportedUrl)&&\PortOpener\Services\RouterConfiguration::validateUrl($reportedUrl)?$reportedUrl:null,'last_reconciled_at'=>$reconciled];
