if(isset($data['status']['ipv6']))$status['ipv6']=\PortOpener\Services\Ipv6Report::sanitize($data['status']['ipv6'],$allowed,$policy->ipv6_mapping_ids ?? []);
if(isset($data['diagnostics']) && ($diagnostics=\PortOpener\Services\NodeDiagnostics::sanitize($data['diagnostics']))){$diagnostics['received_at']=now()->toIso8601String();$policy->service_diagnostics=$diagnostics;}
$policy->forceFill(['last_report'=>$status,'last_contact_at'=>now()])->saveQuietly();
SyncState::where('installation_id',$policy->installation_id)->update(['last_status'=>json_encode($status,JSON_THROW_ON_ERROR),'synced_at'=>now(),'last_error'=>$policy->service_error]);
if(!empty($data['test_request_id']) && $data['test_request_id']===$policy->test_request_id && isset($data['test_result']) && ($policy->test_request_configuration['router_url'] ?? null)===$policy->router_url && ($policy->test_request_configuration['forwarding_type'] ?? null)===$policy->forwarding_type){$test=$data['test_result'];$policy->forceFill(['last_router_test'=>['backend'=>($test['backend'] ?? '')==='fake'?'fake':'upnp','router_reachable'=>($test['router_reachable'] ?? false)===true,'message'=>'Service completed the requested router discovery test.','router_url'=>$policy->router_url,'forwarding_type'=>$policy->forwarding_type],'router_tested_at'=>now(),'test_request_id'=>null,'test_request_configuration'=>null])->saveQuietly();}
\PortOpener\Services\NodeModes::finish($policy);
return response()->json(['accepted'=>true]);});}
}
